      note1: "\u9580\u5E02\u5730\u5740\uFF1A\u53F0\u5317\u5E02\u5927\u540C\u5340\u8FEA\u5316\u88571\u6BB5205\u865F",
      note2: "https://docs.google.com/document/d/1IyhSP526xoHR99tplhyTOF3a8iH7MePJ/edit?usp=sharing&ouid=103956128374093605205&rtpof=true&sd=true",
      try_content: "\u6211\u5011\u662F\u53F0\u5317\u8FEA\u5316\u8857\u516D\u5341\u5E74\u8001\u5E97<br />\r\n\u73FE\u5728\u4EE5\u300C\u60E0\u73CD\u8ED2\u300D\u958B\u555F\u65B0\u7684\u7BC7\u7AE0\u2728<br />\r\n\u5C07\u63D0\u4F9B\u6700\u65B0\u9BAE\u7684\u54C1\u8CEA\u3001\u6700\u5BE6\u60E0\u7684\u50F9\u683C\u3001\u6700\u5065\u5EB7\u7684\u98F2\u98DF\u89C0\u5FF5\uFF01<br />\r\n<br />\r\n\u{1F4CC}\u4E3B\u8981\u8CA9\u552E\u5546\u54C1<br />\r\n\u5E38\u6EAB\uFF1A\u65B0\u9BAE\u5805\u679C\u3001\u7279\u8272\u679C\u4E7E\u3001\u53E4\u65E9\u5473\u96F6\u5634\u3001\u6F8E\u6E56\u4F2F\u5546\u54C1<br />\r\n\u4F4E\u6EAB\uFF1A\u53F0\u5357\u5468\u6C0F\u51B0\u93AE\u6EF7\u5473\u3001\u53F0\u6771\u7389\u7C73\u653E\u5C71\u96DE\u3001\u62DB\u724C\u8089\u6842\u6372<br />\r\n<br />\r\n\u60E0\u73CD\u8ED2\u62DB\u724C\u7CBE\u9078#\u73CD\u5C0F\u5305\uFF0C\u773E\u591A\u71B1\u9580\u54C1\u9805\u5747\u4E00\u50F9$120\u{1F4B0} \u4EFB\u90786\u9805600\u5143<br />\r\n\u5065\u5EB7\u96F6\u5634\u8B93\u60A8\u80FD\u96A8\u6642\u653E\u5728\u5305\u5305\u5E36\u8457\u5403\u{1F60B} \u966A\u4F34\u60A8\u6BCF\u4E00\u523B\u2764\uFE0F<br />\r\n<br />\r\n\uFF0A\u9580\u5E02\u5730\u5740\uFF1A\u53F0\u5317\u5E02\u5927\u540C\u5340\u8FEA\u5316\u88571\u6BB5205\u865F\uFF08\u9580\u53E3\u5925\u4F34\u70BA\u9B5A\u523A\u4EBA\u96DE\u86CB\u7CD5\uFF09<br />\r\n\u5EFA\u8B70\u5230\u5E97\u6642\u9593\uFF1A11-17\u9EDE\u4E4B\u9593\uFF0C\u5E73\u65E5\u4F73\uFF08\u907F\u514D\u5047\u65E5\u4EBA\u6F6E\u8F03\u591A\u4E0D\u597D\u62CD\u7167\u9AD4\u9A57\uFF09<br />\r\n<br />\r\n\u25CE\u6D3B\u52D5\u6D41\u7A0B<br />\r\n1.\u9304\u53D6\u901A\u77E5\uFF1A\u5C07\u900F\u904Eemail\u901A\u77E5\u9304\u53D6\u4E4B\u6703\u54E1\uFF0C\u9304\u53D6\u8005\u9808\u5728\u7279\u5B9A\u671F\u9593\u5167 11:00-17:00\u5230\u5E97\u514C\u63DB\u5546\u54C1\u3002<br />\r\n2.\u5230\u5E97\u9AD4\u9A57\u4E26\u767C\u8868\u9AD4\u9A57\u5FC3\u5F97\uFF1A\u9304\u53D6\u8005\u9700\u5728\u6307\u5B9A\u5929\u6578\u5230\u5E97\u9AD4\u9A57\uFF0C\u6700\u665A\u9700\u65BC10/27\uFF08\u65E5\uFF09\u524D\u5230\u5E97\u9AD4\u9A57\u5B8C\u7562\uFF0C<br />\r\n\u4E26\u65BC\u9AD4\u9A57\u5B8C\u7562\u5F8C\u65BC\u90E8\u843D\u683C\u767C\u8868\u4E00\u7BC7\u9AD4\u9A57\u6587\u7AE0\uFF0C\u4E26\u4F9D\u7167\u4FE1\u4EF6\u6307\u793A\u56DE\u8986\u6587\u7AE0\u9023\u7D50\u3002\uFF08\u7D0414\u5929\uFF0C\u6642\u9593\u4F9D\u5C46\u6642\u9304\u53D6\u4FE1\u4EF6\u901A\u77E5\u70BA\u6E96\uFF09<br />\r\n\uFF0A\u514C\u63DB\u6642\u9700\u8981\u51FA\u793A \u201C\u8EAB\u4EFD\u8B49\u201D \u4EE5\u4F9B\u5E97\u5BB6\u6838\u5C0D\u8EAB\u4EFD\u3002<br />\r\n\uFF0A\u8ACB\u5728\u5831\u540D\u6642\u78BA\u4FDD\u6240\u586B\u5BEB\u7684\u59D3\u540D\u6B63\u78BA\u7121\u8AA4\uFF0C\u4EE5\u907F\u514D\u514C\u63DB\u6642\u51FA\u73FE\u554F\u984C\u3002<br />\r\n3.\u9AD4\u9A57\u6587\u7AE0\u898F\u7BC4\uFF08\u4EE5\u5C46\u6642\u63D0\u4F9B\u64B0\u6587\u5927\u7DB1\u70BA\u6E96\uFF09\uFF1A<br />\r\n\u3010\u6587\u7AE0\u5B57\u6578\u3011500\u5B57\u4EE5\u4E0A\uFF0C\u64B0\u6587\u8ACB\u4EE5\u300E\u4ECB\u7D39\u9580\u5E02\u5546\u54C1\u8CA9\u552E\u300F\u70BA\u4E3B\u3002<br />\r\n\u3010\u7167\u7247\u3011\u81F3\u5C11\u516D\u5F35\u7167\u7247\u4EE5\u4E0A\uFF0C\u9700\u6E05\u695A\u62CD\u5230\u9580\u5E02\u54C1\u724C\u3001\u5E97\u5167\u5546\u54C1\uFF0C\u5982\u80FD\u62CD\u77ED\u5F71\u7247\u66F4\u597D\u3002",
